    out = [row[:] for row in grid]
    centers = []

    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[y][x] == 3
                for y in range(r - 1, r + 2)
                for x in range(c - 1, c + 2)
                if (y, x) != (r, c)
            ):
                centers.append((r, c))

    for r, c in centers:
        vertical = sum(grid[y][c] == 2 for y in range(h)) >= h - 3
        horizontal = sum(grid[r][x] == 2 for x in range(w)) >= w - 3

        if vertical:
            # A vertical 2-line through the object sends a horizontal ray.
            for x in range(w):
                if out[r][x] == 0:
                    out[r][x] = 1

            # At each other vertical 2-line, make the 3x3 flare.
            for x in range(w):
