                        for xx in range(max(0, x - 1), min(w, x + 2)):
                            if (y, xx) != (r, x) and out[y][xx] != 3:
                                out[y][xx] = 1

        elif horizontal:
            # A horizontal 2-line through the object sends a vertical ray.
            for y in range(h):
                if out[y][c] == 0:
                    out[y][c] = 1

            # At each other horizontal 2-line, make the 3x3 flare.
            for y in range(h):
                if y != r and grid[y][c] == 2:
                    for yy in range(max(0, y - 1), min(h, y + 2)):
                        for x in range(max(0, c - 1), min(w, c + 2)):
